package palindrome

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// Product holds a palindromic product and all the factor pairs
// (within the given range) that produce it.
type Product struct {
	Product       int
	Factorizations [][2]int
}

// Products finds the smallest and largest palindromic products
// of two numbers in the range [fmin, fmax], inclusive.
func Products(fmin, fmax int) (Product, Product, error) {
	if fmin > fmax {
		return Product{}, Product{}, errors.New("fmin > fmax")
	}

	type candidate struct {
		product int
		factors [2]int
	}

	var candidates []candidate
	for i := fmin; i <= fmax; i++ {
		for j := i; j <= fmax; j++ {
			p := i * j
			if isPalindrome(p) {
				candidates = append(candidates, candidate{p, [2]int{i, j}})
			}
		}
	}

	if len(candidates) == 0 {
		return Product{}, Product{}, errors.New("no palindromes")
	}

	// Sort by product value, then by factors, so the first candidate
	// is the smallest palindrome and the last is the largest.
	sort.Slice(candidates, func(a, b int) bool {
		if candidates[a].product != candidates[b].product {
			return candidates[a].product < candidates[b].product
		}
		if candidates[a].factors[0] != candidates[b].factors[0] {
			return candidates[a].factors[0] < candidates[b].factors[0]
		}
		return candidates[a].factors[1] < candidates[b].factors[1]
	})

	min := Product{Product: candidates[0].product}
	for _, c := range candidates {
		if c.product == min.Product {
			min.Factorizations = append(min.Factorizations, c.factors)
		}
	}

	max := Product{Product: candidates[len(candidates)-1].product}
	for _, c := range candidates {
		if c.product == max.Product {
			max.Factorizations = append(max.Factorizations, c.factors)
		}
	}

	return min, max, nil
}

// isPalindrome reports whether n is a palindromic number.
func isPalindrome(n int) bool {
	s := strconv.Itoa(n)
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		if s[i] != s[j] {
			return false
		}
	}
	return true
}

var _ = fmt.Sprintf // keep fmt import if unused in future edits

